function upgradeState(input){const next=input&&input.product&&Array.isArray(input.customers)?input:seed();if(!next.insights)next.insights={};if(!next.planBooks)next.planBooks={};let p=next.product;if(p.knowledgeSchema!==3){const official=officialProduct();const legacy={version:p.version,rule:p.rule,facts:p.facts,effective:p.effective,scope:p.scope,sourceType:p.sourceType,source:p.source,sourceStatus:p.sourceStatus,reviewer:p.reviewer,reviewedAt:p.reviewedAt,changeReason:p.changeReason||'旧产品资料'};next.product={...official,version:(Number(p.version)||1)+1,history:[legacy,...(p.history||[])]};p=next.product;next.drafts={};next.insights={};}for(const customer of next.customers){customer.tags=(customer.tags||[]).map(item=>item.replace(/示例年金 A|长期年金保险方案|太保蛮好的人生年金保险（互联网）/g,'太保蛮好的人生（2025）年金保险（互联网）'));for(const key of ['gender','plan','paymentTerm','premium','receiveMode','pensionAccount'])if(!customer[key])customer[key]='待确认';}for(const activity of next.activities||[]){activity.note=String(activity.note||'').replace('虚构活动，仅演示预约咨询，不涉及收益优惠。','预约一对一养老资金需求梳理；不涉及收益承诺，参与前核对活动适用范围。').replace('已结束的模拟活动，保留原始规则。','活动已结束，历史规则保留供复盘，不再生成推广话术。');}return next;}
